sop:
@f1 w.request.filler text=thanks
@r1 w.request.request act=change mood=do words="show me a greenhouse in the sun" predicate=show
@r1.t w.request.target request=$r1 family=page mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=page.weather value=sun words="in the sun" operator=eq phase=result
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=page.scene value=greenhouse operator=eq phase=result
@r2 w.request.request act=make mood=do words="a small lady with a happy face next to the shelf"
@r2.t w.request.target request=$r2 family=drawn mode=new determiner=indefinite sort=lady
@r2.c1 w.request.constraint request=$r2 on=size attribute=drawn.size value=small operator=degree phase=result
@r2.c2 w.request.constraint request=$r2 on=place attribute=drawn.relation value="next to" words="next to the shelf" operator=relation phase=result open_value=true
@r2.c3 w.request.constraint request=$r2 on=attribute attribute=drawn.expression value=happy operator=eq phase=result key_words=face
@r2.c4 w.request.constraint request=$r2 on=place attribute=drawn.anchor value="the shelf" operator=relation phase=selector
@r3 w.request.request act=make mood=do words="five small pink orchids in a row right on the shelf"
@r3.t w.request.target request=$r3 family=drawn mode=new determiner=quantified sort=orchid sort_words=orchids
@r3.c1 w.request.constraint request=$r3 on=count attribute=drawn.count words=five operator=eq phase=result
