@r3.c5 w.request.constraint request=$r3 on=place attribute=drawn.anchor value="the shelf" operator=relation phase=selector
@r3.c6 w.request.constraint request=$r3 on=attribute attribute=drawn.arrangement value=row words="in a row" operator=eq phase=result
@r4 w.request.request act=make mood=do words="two small blue butterflies right around the orchid"
@r4.t w.request.target request=$r4 family=drawn mode=new determiner=quantified sort=butterfly sort_words=butterflies
@r4.c1 w.request.constraint request=$r4 on=count attribute=drawn.count words=two operator=eq phase=result
@r4.c2 w.request.constraint request=$r4 on=size attribute=drawn.size value=small operator=degree phase=result
@r4.c3 w.request.constraint request=$r4 on=attribute attribute=drawn.colour value=blue operator=eq phase=result
@r4.c4 w.request.constraint request=$r4 on=place attribute=drawn.relation value=around words="right around the orchid" operator=relation phase=result
@r4.c5 w.request.constraint request=$r4 on=place attribute=drawn.anchor value="the orchid" operator=relation phase=selector
@r5 w.request.request act=make mood=do words="three small orange pots under the shelf"
@r5.t w.request.target request=$r5 family=drawn mode=new determiner=quantified sort=pot sort_words=pots
@r5.c1 w.request.constraint request=$r5 on=count attribute=drawn.count words=three operator=eq phase=result
